package codemode

import (
	"bytes"
	"compress/gzip"
	"context"
	_ "embed"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/SuInk/diana/internal/procgroup"
)

// Generated by scripts/codemode/build.mjs from integrity-locked npm packages.
//
//go:embed runtime.json.gz
var runtimeBundle []byte

// Prepare extracts trusted code into a private directory. The caller must call
// cleanup after all executions finish. No npm install or network access occurs.
func Prepare(ctx context.Context) (runtime Runtime, cleanup func(), err error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	node, err := exec.LookPath("node")
	if err != nil {
		return runtime, nil, fmt.Errorf("codemode requires Node >=22.19: %w", err)
	}
	cmd := procgroup.CommandContext(ctx, node, "--version")
	cmd.Env = hostEnvironment()
	output, err := cmd.Output()
	if err != nil || !supportedNodeVersion(strings.TrimSpace(string(output))) {
		return runtime, nil, fmt.Errorf("codemode requires Node >=22.19 (version probe failed or unsupported)")
	}
	dir, err := os.MkdirTemp("", "diana-codemode-*")
	if err != nil {
		return runtime, nil, err
	}
	cleanup = func() { _ = os.RemoveAll(dir) }
	if err := extractBundle(dir); err != nil {
		cleanup()
		return runtime, nil, err
	}
	return Runtime{Node: node, Host: filepath.Join(dir, "host.mjs")}, cleanup, nil
}

func supportedNodeVersion(version string) bool {
	parts := strings.Split(strings.TrimPrefix(version, "v"), ".")
	if len(parts) != 3 {
		return false
	}
	major, err1 := strconv.Atoi(parts[0])
	minor, err2 := strconv.Atoi(parts[1])
	_, err3 := strconv.Atoi(parts[2])
	return err1 == nil && err2 == nil && err3 == nil && (major > 22 || major == 22 && minor >= 19)
}

func extractBundle(dir string) error {
	zr, err := gzip.NewReader(bytes.NewReader(runtimeBundle))
	if err != nil {
		return err
	}
	defer zr.Close()
	var files map[string][]byte
	if err := json.NewDecoder(io.LimitReader(zr, 8*1024*1024)).Decode(&files); err != nil {
		return err
	}
	for name, data := range files {
		if !filepath.IsLocal(name) || strings.Contains(name, "\\") {
			return fmt.Errorf("invalid embedded runtime path %q", name)
		}
		path := filepath.Join(dir, filepath.FromSlash(name))
		if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
			return err
		}
		if err := os.WriteFile(path, data, 0600); err != nil {
			return err
		}
	}
	return nil
}
